import { ArrowUpRight } from 'lucide-react';
import { GitHubIcon } from '../SocialIcons.jsx';

const GITHUB_USER = 'NgetMeas22';
const GITHUB_URL = `https://github.com/${GITHUB_USER}`;
const SNAKE_BASE = `https://raw.githubusercontent.com/${GITHUB_USER}/${GITHUB_USER}/output`;

// Contribution "snake" animation generated by the Platane/snk GitHub Action
// on the profile repo. It refreshes on GitHub; nothing to build here.
export default function GitHubSnake({ isDark, t }) {
  const src = `${SNAKE_BASE}/github-contribution-grid-snake${isDark ? '-dark' : ''}.svg`;

  return (
    <div
      className={`relative overflow-hidden rounded-2xl sm:rounded-3xl border-2 p-4 sm:p-8 ${
        isDark
          ? 'border-emerald-800/60 bg-black/80 shadow-[0_0_30px_rgba(16,185,129,0.08)]'
          : 'border-emerald-200 bg-white shadow-xs'
      }`}
      data-aos="fade-up"
    >
      <div className="mb-4 sm:mb-6 flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <span
            className={`inline-flex h-10 w-10 items-center justify-center rounded-xl border ${
              isDark
                ? 'border-emerald-500/40 bg-emerald-950/40 text-emerald-300'
                : 'border-emerald-300 bg-emerald-50 text-emerald-700'
            }`}
          >
            <GitHubIcon className="h-5 w-5" />
          </span>
          <div>
            <p className={`text-sm sm:text-base font-bold ${isDark ? 'text-white' : 'text-slate-900'}`}>
              @{GITHUB_USER}
            </p>
            <p className={`text-xs ${isDark ? 'text-slate-400' : 'text-slate-600'}`}>
              {t.home.snakeSubtitle}
            </p>
          </div>
        </div>
        <a
          href={GITHUB_URL}
          target="_blank"
          rel="noopener noreferrer"
          className={`inline-flex items-center gap-1.5 rounded-lg border px-3 py-2 text-xs font-bold uppercase tracking-wider transition-colors ${
            isDark
              ? 'border-emerald-500/40 text-emerald-300 hover:bg-emerald-500/10'
              : 'border-emerald-300 text-emerald-800 hover:bg-emerald-50'
          }`}
        >
          {t.home.viewGitHub}
          <ArrowUpRight className="h-3.5 w-3.5" />
        </a>
      </div>

      <a href={GITHUB_URL} target="_blank" rel="noopener noreferrer" className="block overflow-x-auto">
        <img
          src={src}
          alt={t.home.snakeTitle}
          loading="lazy"
          className="mx-auto h-auto w-full min-w-[640px] max-w-5xl"
        />
      </a>
    </div>
  );
}
